local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end;local function eq(a,b)if a~=b then error(tostring(a).." ~= "..tostring(b),2)end end
local C=load_submission("lua/rhenium_hot_object_round/controller.lua");local function fresh(v,s)local c=assert(C.new({object_id="hot:1",object_revision=1,state=s}));if not s then assert(c:start("start","round:1",v or"exploding",{"A","B","C"},"A",10))end;return c end
case("round starts with three stable players and frozen deadline",function()local c=fresh();local s=c:snapshot();eq(s.status,"active");eq(s.holder,"A");eq(s.deadline,10)end)
case("monotonic touch sequence transfers holder",function()local c=fresh();assert(c:touch("t1","hot:1",1,"B",1,1,2));assert(c:touch("t2","hot:1",1,"C",1,2,2));eq(c:snapshot().holder,"C");local ok,e=c:touch("t3","hot:1",1,"A",1,1,2);assert(not ok);eq(e,"stale_sequence")end)
case("event replay is exact and conflicts fail",function()local c=fresh();assert(c:touch("t","hot:1",1,"B",1,1,2));assert(c:touch("t","hot:1",1,"B",1,1,2));local ok,e=c:touch("t","hot:1",1,"C",1,2,2);assert(not ok);eq(e,"event_conflict")end)
case("wrong object generation and dead player never transfer",function()local c=fresh();local ok,e=c:touch("x","hot:1",2,"B",1,1,1);assert(not ok);eq(e,"wrong_object");assert(c:death("d","B",1,2));ok,e=c:touch("y","hot:1",1,"B",1,1,3);assert(not ok);eq(e,"invalid_player")end)
case("holder death and disconnect choose stable successor",function()local c=fresh();assert(c:death("d","A",1,1));eq(c:snapshot().holder,"B");assert(c:disconnect("x","B",1,2));eq(c:snapshot().holder,"C")end)
case("respawn creates a new player revision",function()local c=fresh();assert(c:death("d","B",1,1));assert(c:respawn("r","B",1,2,2));local ok,e=c:touch("t","hot:1",1,"B",1,1,3);assert(not ok);ok,e=c:touch("t2","hot:1",1,"B",2,1,3);assert(ok,e)end)
case("deadline settles exploding round exactly once",function()local c=fresh("exploding");assert(c:touch("t","hot:1",1,"B",1,1,9));c:tick(10);local s=c:snapshot();eq(s.status,"finished");eq(s.result.holder,"B");eq(s.settlements,1);c:tick(10);eq(c:snapshot().settlements,1)end)
case("infectious variant excludes every infected survivor from winners",function()local c=fresh("infectious");assert(c:touch("t1","hot:1",1,"B",1,1,4));assert(c:touch("t2","hot:1",1,"C",1,2,5));c:tick(10);local s=c:snapshot();eq(s.result.variant,"infectious");eq(s.result.holder,"C");eq(#s.result.winners,1);eq(s.result.winners[1],"A");assert(s.players and s.players.B.infected or s.player_rows and s.player_rows[2].infected)end)
case("time reversal cannot reopen or delay settlement",function()local c=fresh();c:tick(10);c:tick(1);eq(c:snapshot().status,"finished");eq(c:snapshot().last_now,10)end)
case("finished transitions to cleanup without second consequence",function()local c=fresh();c:tick(10);c:tick(11);local s=c:snapshot();eq(s.status,"cleanup");eq(s.settlements,1)end)
case("save load preserves audit result and deduplication",function()local c=fresh();assert(c:touch("t","hot:1",1,"B",1,1,2));c:tick(10);local d=fresh(nil,c:save());assert(d:touch("t","hot:1",1,"B",1,1,2));eq(d:snapshot().settlements,1);assert(#d:snapshot().audit>=3)end)
case("same tick ordering is sequence then stable identity",function()local c=fresh();assert(c:touch("z","hot:1",1,"C",1,1,4));assert(c:touch("a","hot:1",1,"B",1,2,4));eq(c:snapshot().holder,"B")end)
case("shutdown is idempotent and freezes events",function()local c=fresh();assert(c:shutdown());assert(c:shutdown());local ok,e=c:touch("t","hot:1",1,"B",1,1,2);assert(not ok);eq(e,"shutdown")end)
case("malformed players events audit result and revisions are rejected",function()local c=fresh("infectious");assert(c:touch("t","hot:1",1,"B",1,1,2));local variants={};local function add(change)local s=c:save();change(s);variants[#variants+1]=s end;add(function(s)s.last_sequence=-1 end);add(function(s)s.audit="bad"end);add(function(s)if s.players then s.players.A.revision=0 else s.player_rows[1].revision=0 end end);add(function(s)if s.seen then local _,e=next(s.seen);e.ok="yes"else s.event_rows[1].ok="yes"end end);add(function(s)if s.players then s.players.extra={revision=1,alive=true,connected=true,infected=false}else s.player_rows[4]=s.player_rows[1]end end);for _,s in ipairs(variants)do local loaded,code=C.new({object_id="hot:1",object_revision=1,state=s});assert(loaded==nil);eq(code,"invalid_state")end end)
return{cases=cases}
